from storage import save_todos

def complete_todo(todo_list):
    if not isinstance(todo_list, list):
        raise TypeError("Input must be a list")
    try:
        todo_list.append("Done")
        save_todos(todo_list, "todos.json")
    except Exception as e:
        raise RuntimeError(f"Failed to save todos: {str(e)}") from e
